import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.CdvW4CUT.js";const i=JSON.parse('{"title":"第 23 章　未解问题与 2027 路线图","description":"","frontmatter":{},"headers":[],"relativePath":"07-conclusion/23-未解问题与2027路线图.md","filePath":"07-conclusion/23-未解问题与2027路线图.md","lastUpdated":1793361704000}'),u={name:"07-conclusion/23-未解问题与2027路线图.md"};function n(q,t,p,d,h,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-23-章-未解问题与-2027-路线图" tabindex="-1">第 23 章　未解问题与 2027 路线图 <a class="header-anchor" href="#第-23-章-未解问题与-2027-路线图" aria-label="Permalink to &quot;第 23 章　未解问题与 2027 路线图&quot;">​</a></h1><p>前面二十二章的方法都建立在一个前提上：记忆系统能判断&quot;什么是该记住的&quot;。这个前提在多数时候成立，但在五处不成立，而这五处恰好是记忆从&quot;功能&quot;走向&quot;基础设施&quot;必须跨过的关口。</p><p>本章不试图给出解法。它的价值在于把边界画清楚：哪些问题已经被解决到可以生产使用，哪些仍处在&quot;有方案但没有验证&quot;的阶段，哪些连问题本身都还没被定义。这个区分对投入决策很关键——为一个已解决的问题投入是重复劳动，为一个未被定义的问题投入是赌博。</p><h2 id="_23-1-五个未解问题" tabindex="-1">23.1 五个未解问题 <a class="header-anchor" href="#_23-1-五个未解问题" aria-label="Permalink to &quot;23.1 五个未解问题&quot;">​</a></h2><h3 id="_23-1-1-记忆的正确性由谁定义" tabindex="-1">23.1.1 记忆的正确性由谁定义 <a class="header-anchor" href="#_23-1-1-记忆的正确性由谁定义" aria-label="Permalink to &quot;23.1.1 记忆的正确性由谁定义&quot;">​</a></h3><p>所有系统都默认&quot;用户说的事实就是记忆&quot;。这个默认在多数场景下合理，但在三种情况下失效：用户记错了、用户说反了、用户故意误导。</p><p>具体场景：用户说&quot;我对花生过敏&quot;，但此前的医疗记录显示没有过敏史。系统应该记住哪一个？如果相信用户，可能造成不必要的饮食限制；如果相信记录，可能在用户真的过敏时造成危险。</p><p>技术上可以做的裁决手段有限。交叉验证需要外部事实源，而多数系统没有接入；时间优先假设&quot;新的更准&quot;，但新信息也可能来自更不可靠的来源；来源优先假设&quot;正式的更准&quot;，但正式来源也可能过期。</p><p>真正的问题在于：这个裁决规则是<strong>业务规则</strong>，不是技术规则。它应该由使用方定义，而当前所有系统都把它硬编码成&quot;相信用户&quot;。这意味着系统在替使用方做医疗、金融、法律层面的判断，而这个判断的依据从未被明示。</p><p>截至 2026 年 10 月，没有一个系统在生产中实现了可配置的事实裁决规则。这是第一个未解问题，也是最基础的一个。</p><h3 id="_23-1-2-多-agent-共享记忆的冲突仲裁" tabindex="-1">23.1.2 多 Agent 共享记忆的冲突仲裁 <a class="header-anchor" href="#_23-1-2-多-agent-共享记忆的冲突仲裁" aria-label="Permalink to &quot;23.1.2 多 Agent 共享记忆的冲突仲裁&quot;">​</a></h3><p>当一个用户的三个 Agent（工作助手、个人助理、健康顾问）共享同一份记忆时，谁有权写入、谁有权删除、冲突如何仲裁？</p><p>物理隔离支持&quot;不共享&quot;——每个 Agent 一个作用域，各自独立。这是当前唯一可靠的方案。代价是用户需要在三个 Agent 之间重复表述同样的偏好。</p><p>共享则需要权限模型，而权限模型的复杂度会随 Agent 数量与共享范围爆炸。三个 Agent 两两共享有 3 种关系，五个 Agent 有 10 种，且每种关系需要定义读权限、写权限、删除权限、可见性范围。</p><p>当前的产品级方案大致有两类。一类是&quot;共享读、隔离写&quot;：多个 Agent 可以读同一份受治理的记忆，写入仍各自隔离。这避免了写冲突仲裁，代价是共享层需要定期合并，存在延迟。另一类是&quot;组织级共享仓库&quot;：把共享记忆做成一个独立的、由组织拥有的仓库，各 Agent 按权限访问。这类方案通常要求云托管环境，本地部署的 Agent 无法参与。</p><p>两类方案都没有解决核心问题：当两个 Agent 对同一事实给出不同结论时，谁对？这个问题在单 Agent 场景下不存在，在多 Agent 场景下必然出现，而当前没有仲裁机制。</p><h3 id="_23-1-3-遗忘的可验证性" tabindex="-1">23.1.3 遗忘的可验证性 <a class="header-anchor" href="#_23-1-3-遗忘的可验证性" aria-label="Permalink to &quot;23.1.3 遗忘的可验证性&quot;">​</a></h3><p>第 13 章已经展开：哈希链能证明&quot;未被篡改&quot;，不能证明&quot;已不存在&quot;。</p><p>这个问题的难点不在技术，在逻辑。要证明一个否定命题（&quot;某信息已不存在于系统中任何位置&quot;），需要穷举所有可能位置并逐一验证。而位置清单本身会随系统演进变化——今天加了缓存层，昨天做的证明就失效了。</p><p>更麻烦的是证明本身会留下痕迹。为了证明&quot;已删除&quot;而保留一份删除记录，这份记录包含&quot;曾经存在过某条信息&quot;这一事实，可能构成新的个人信息。这是一个自指困境。</p><p>可能的方向是把否定命题转化为可核查的清单比对：不证明&quot;不存在&quot;，而是记录&quot;在哪些位置、由谁、在什么时间、执行了何种处理&quot;，并允许第三方复核这些处理是否覆盖了其已知的所有位置。这个思路降低了难度，但截至 2026 年 10 月还没有形成标准格式。</p><h3 id="_23-1-4-基准与真实使用之间的鸿沟" tabindex="-1">23.1.4 基准与真实使用之间的鸿沟 <a class="header-anchor" href="#_23-1-4-基准与真实使用之间的鸿沟" aria-label="Permalink to &quot;23.1.4 基准与真实使用之间的鸿沟&quot;">​</a></h3><p>现有基准测的都是<strong>被动检索</strong>：给定一个查询，看系统能否返回正确的记忆。</p><p>但真实使用中，用户会主动管理记忆——编辑、删除、重新表述、追问&quot;你为什么记得这个&quot;。这些交互模式与被动检索的评估范式完全不同。</p><p>具体场景：用户发现系统记错了自己的职业，说&quot;不对，我是设计师不是工程师&quot;。系统正确响应需要三步：识别这是一次纠正、定位到错误记忆、更新并确认。现有基准不测这三步中的任何一步。</p><p>后果是：一个在 LongMemEval 上拿到高分的系统，可能在用户纠正时反复犯错——它记住了新信息，但旧信息仍在，下次检索可能返回旧的。这个失效在基准上完全不可见。</p><p>第二个鸿沟是<strong>长周期使用</strong>。LongMemEval 论文报告的约 30% 准确率下降已经提示了这个问题，但下降的机制没有被充分研究。是记忆条目增多导致检索精度下降？是旧事实干扰？还是用户偏好本身在变化？不同机制需要不同解法，而当前无法区分。</p><h3 id="_23-1-5-成本与质量的帕累托前沿" tabindex="-1">23.1.5 成本与质量的帕累托前沿 <a class="header-anchor" href="#_23-1-5-成本与质量的帕累托前沿" aria-label="Permalink to &quot;23.1.5 成本与质量的帕累托前沿&quot;">​</a></h3><p>单次记忆写入的模型调用成本、嵌入生成成本、检索时的融合计算成本，与召回质量之间的关系，没有公开的跨系统数据。</p><p>这意味着选型时无法回答一个基本问题：多花一倍成本，能换来多少质量提升？</p><p>具体场景：一个团队在&quot;配置更强的嵌入模型&quot;与&quot;增加重排器&quot;之间选择。前者每次写入成本上升，后者每次检索成本上升。哪个更划算？答案取决于写入与检索的比例、语料特征、以及对召回精度的实际需求。而这些参数在真实场景中差异极大，任何单一建议都不适用。</p><p>可行的方法是自己做小规模对照实验：固定一批查询与 ground truth，分别测三种配置的召回率与成本。这个方法可靠但费时，而多数团队在选型阶段不愿意投入。</p><p>没有公开的成本-质量曲线，选型只能依赖经验与厂商推荐，而厂商推荐天然有偏向。</p><h2 id="_23-2-2027-路线图" tabindex="-1">23.2 2027 路线图 <a class="header-anchor" href="#_23-2-2027-路线图" aria-label="Permalink to &quot;23.2 2027 路线图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>2026 状态</th><th>2027 预期</th><th>关键不确定性</th></tr></thead><tbody><tr><td>可配置的事实裁决</td><td>全部硬编码&quot;相信用户&quot;</td><td>出现可配置的裁决策略（来源优先/时间优先/人工确认）</td><td>使用方是否愿意承担配置责任</td></tr><tr><td>跨 Agent 记忆治理</td><td>物理隔离为主，共享读为辅</td><td>共享读成熟，共享写出现参考实现</td><td>权限模型复杂度是否可控</td></tr><tr><td>遗忘的可验证性</td><td>各家自定义处理记录</td><td>出现可交换的删除审计格式</td><td>标准化组织是否介入</td></tr><tr><td>主动管理行为的评测</td><td>无基准覆盖</td><td>出现针对纠正、删除、追问的评测集</td><td>标注成本高，难以规模化</td></tr><tr><td>成本-质量曲线</td><td>无公开数据</td><td>头部厂商公布对照数据</td><td>公布数据即暴露成本结构</td></tr><tr><td>中文与非英语场景</td><td>少数实现做针对性优化</td><td>出现独立的非英语基准</td><td>数据集构建与标注成本</td></tr></tbody></table><p>表 23-1　2027 年可预期的演进方向</p><p>这张表的第四列比第三列更重要。每一个方向的进展都受制于一个非技术因素：使用方是否愿意承担配置责任、权限模型复杂度是否可控、标准化组织是否介入、标注成本是否可承受、厂商是否愿意暴露成本结构。技术能力不是瓶颈，激励结构才是。</p><h2 id="_23-3-给五类角色的行动建议" tabindex="-1">23.3 给五类角色的行动建议 <a class="header-anchor" href="#_23-3-给五类角色的行动建议" aria-label="Permalink to &quot;23.3 给五类角色的行动建议&quot;">​</a></h2><h3 id="_23-3-1-开发者" tabindex="-1">23.3.1 开发者 <a class="header-anchor" href="#_23-3-1-开发者" aria-label="Permalink to &quot;23.3.1 开发者&quot;">​</a></h3><p>不要在建&quot;又一个记忆存储&quot;。存储层已经过剩，单遍 ADD-only 加多信号检索是公开可复制的方案。</p><p>机会在三处。第一处是<strong>观测层</strong>：trace、审计、质量监控、成本归因。这些工具目前普遍薄弱，而它们决定了系统出问题时能否被快速定位。第二处是<strong>场景适配层</strong>：中文分词、专有名词检索、行业术语，这些是通用方案覆盖不到的。第三处是<strong>前置条件建模</strong>：如何把&quot;经验&quot;与&quot;建议&quot;区分开，如何让经验的适用条件可被机器校验。</p><p>三处的共同点是：它们都不需要新算法，需要对具体场景的深入理解。</p><h3 id="_23-3-2-架构师" tabindex="-1">23.3.2 架构师 <a class="header-anchor" href="#_23-3-2-架构师" aria-label="Permalink to &quot;23.3.2 架构师&quot;">​</a></h3><p>在 2027 年的选型中，把&quot;是否支持逐条来源追溯&quot;作为硬性门槛。</p><p>理由不是追溯本身有价值，而是没有追溯能力的系统在事故复盘时无法定位。一次记忆导致的事故，如果无法回答&quot;这条记忆从哪来&quot;，复盘就只能停在&quot;系统表现异常&quot;，无法进入&quot;为什么异常&quot;。</p><p>第二项门槛是&quot;删除是否分级&quot;。只会做单条删除的系统，在合规场景下不达标；只做物理删除的系统，在产品场景下过度销毁。</p><p>第三项是&quot;隔离是否可举证&quot;。不是问&quot;是否隔离&quot;，而是问&quot;能否用三项测试证明隔离&quot;。</p><h3 id="_23-3-3-产品负责人" tabindex="-1">23.3.3 产品负责人 <a class="header-anchor" href="#_23-3-3-产品负责人" aria-label="Permalink to &quot;23.3.3 产品负责人&quot;">​</a></h3><p>用户对记忆的信任，取决于用户能否理解系统记住了什么以及为什么。</p><p>三个具体做法。第一，<strong>分层展示</strong>：把记忆按稳定身份、偏好约束、当前情境分层，让用户看到结构而不是平铺列表。第二，<strong>纠正成本最小化</strong>：用户说&quot;不对&quot;之后，系统应当在一次交互内完成定位、更新、确认三步。第三，<strong>给&quot;别记这个&quot;一个中间选项</strong>：完全删除会破坏连续性，完全不删违背用户意愿，掩码是两者之间的实用折中。</p><p>三个做法都不需要新技术，需要的是把记忆当作产品界面来设计，而不是当作后台功能来实现。</p><h3 id="_23-3-4-合规与安全" tabindex="-1">23.3.4 合规与安全 <a class="header-anchor" href="#_23-3-4-合规与安全" aria-label="Permalink to &quot;23.3.4 合规与安全&quot;">​</a></h3><p>2027 年最紧迫的工作不是增加检查项，而是把删除的预览输出纳入变更管理。</p><p>一条被删除的用户偏好可能已经影响了三次推荐结果。删除的爆炸半径必须在执行前可见，而这个可见性需要流程支撑——预览、审批、执行、归档四步，缺任何一步都会在审查时被追问。</p><p>第二项工作是区分&quot;我们删了&quot;与&quot;我们能证明按流程删了&quot;。前者是陈述，后者是证据。多数团队停在陈述，而审查方要的是证据。</p><p>第三项是不要为&quot;已彻底清除&quot;背书。当前技术给不出这个证明，承诺它会在第一次深度审查时崩塌。</p><h3 id="_23-3-5-研究者" tabindex="-1">23.3.5 研究者 <a class="header-anchor" href="#_23-3-5-研究者" aria-label="Permalink to &quot;23.3.5 研究者&quot;">​</a></h3><p>工业界最缺的不是新算法，而是<strong>可复现的失败案例集</strong>。</p><p>一个公开的&quot;记忆系统失败模式基准&quot;，记录每个系统在特定场景下的具体崩塌方式，其价值会超过任何单个系统的 headline 分数。原因是：分数告诉你好不好，失败案例告诉你哪里会坏，而后者对工程决策更有用。</p><p>第二个方向是<strong>主动管理行为的评测</strong>。用户纠正、删除、追问时系统的响应质量，是当前完全空白的区域，也是真实使用中最频繁的交互。</p><p>第三个方向是<strong>成本-质量曲线的公开测量</strong>。这件事需要中立第三方，因为厂商没有动力公布对自己不利的数据。</p><h2 id="_23-4-结语" tabindex="-1">23.4 结语 <a class="header-anchor" href="#_23-4-结语" aria-label="Permalink to &quot;23.4 结语&quot;">​</a></h2><p>记忆系统的成熟标志不是记住更多。</p><p>一个记住一切的系统，在用户看来是可怕而非可靠——因为它无法被推翻。一个记得精准但无法解释的系统，在运维看来是黑盒而非工具——因为出问题时无从下手。一个能删干净但证不出来的系统，在合规看来是隐患而非资产——因为它的承诺无法被验证。</p><p>因此真正的成熟标志是三条：<strong>能被解释</strong>（每个结论可追溯到来源）、<strong>能被推翻</strong>（用户纠正后系统确实改变）、<strong>能被彻底遗忘</strong>（删除覆盖全部层次且有据可查）。</p><p>三条都不涉及&quot;记得更多&quot;。它们涉及的是控制权——用户对记忆的控制权，运维对系统的控制权，合规对证据的控制权。</p><p>2026 年的技术条件已经足以实现前两条。第三条受制于一个尚未解决的自指困境，短期内不会消失。承认这一点，比宣称解决它更接近工程诚实。</p><p>记忆最终会像数据库一样，成为一个不需要被反复讨论的基础设施。到那时，人们不再问&quot;你的记忆系统用什么算法&quot;，而是问&quot;它能不能被审计、被推翻、被遗忘&quot;——就像今天问数据库&quot;能不能事务、能不能备份、能不能恢复&quot;一样。</p><p>那一天到来之前，本书讨论的这些取舍仍然需要被逐项做出来。</p><hr>',70)])])}const _=o(u,[["render",n]]);export{i as __pageData,_ as default};
